'use strict';
(()=>{
 const model=window.AtlasEvaluation,tr=x=>typeof x==='string'?x:x?.[window.AtlasLanguage.current()]||x?.en||'',t=(zh,en)=>window.AtlasLanguage.current()==='zh'?zh:en;
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let current=[],context={},mode='resources',choices={},extras=[],different=false;
 const names={task:['任务目标','Task objective'],observation:['观测接口','Observation'],action:['动作接口','Actions'],metrics:['原始评价指标','Native metrics'],controls:['配置与预算','Configuration & budget'],limits:['适用范围','Scope']};
 const missing=()=>t('此范围尚无已整理的原始任务协议','No documented task protocol in this scope');
 function options(id){return window.AtlasResearchArchives.get(id).tasks.filter(p=>p.origin!=='arena-documented-candidate'&&(!context.gameId||p.gameIds.includes(context.gameId)));}
 function read(){const p=new URLSearchParams(location.search);mode=p.get('compareMode')==='tasks'?'tasks':'resources';different=p.get('compareDiff')==='1';try{choices=JSON.parse(p.get('compareTasks')||'{}');if(!choices||Array.isArray(choices)||typeof choices!=='object')choices={};extras=JSON.parse(p.get('compareExtras')||'[]');if(!Array.isArray(extras))extras=[];}catch{choices={};extras=[];}extras=extras.filter(id=>current.includes(id)).slice(0,Math.max(0,4-current.length));}
 function sync(){const u=new URL(location.href);u.searchParams.set('compareMode',mode);u.searchParams.set('compareTasks',JSON.stringify(choices));u.searchParams.set('compareExtras',JSON.stringify(extras));if(different)u.searchParams.set('compareDiff','1');else u.searchParams.delete('compareDiff');history.replaceState({},'',u);}
 function slots(){const occurrences={};return [...current,...extras].slice(0,4).map((id,i)=>{const a=window.AtlasResearchArchives.get(id),opts=options(id),key=id+':'+(occurrences[id]||0);occurrences[id]=(occurrences[id]||0)+1;const p=opts.find(u=>u.id===choices[key])||opts.find(u=>context.question&&u.capabilities.some(c=>c.id===context.question.cap))||opts[0]||null;return {id,a,opts,key,p};});}
 const pairs=rows=>{const out=[];for(let i=0;i<rows.length;i++)for(let j=i+1;j<rows.length;j++)if(rows[i].p&&rows[j].p)out.push({a:rows[i],b:rows[j],relation:model.pair(rows[i].p.id,rows[j].p.id)});return out;};
 function resourceRows(){return [
 [t('研究用途','Research use'),s=>s.a.overview?.sections.find(x=>x.key==='research')?.body||s.a.bibliography.scope||s.a.profile.research?.fit||null],
 [t('任务与环境','Tasks & environment'),s=>s.a.overview?.sections.find(x=>x.key==='task')?.body||s.a.profile.research?.scope||null],
 [t('评价方式','Evaluation'),s=>s.a.overview?.sections.find(x=>x.key==='evaluation')?.body||s.a.bibliography.metrics||null],
 [t('适用范围','Scope'),s=>s.a.overview?.sections.find(x=>x.key==='scope')?.body||s.a.bibliography.limits||null],
 [t('Agent 使用记录','Documented agent use'),s=>s.a.bibliography.agents.join(' / ')],
 [t('可进一步对比的协议','Protocols available for comparison'),s=>String(s.opts.length)]];}
 function taskRows(){return [...Object.entries(names).map(([k,n])=>[t(...n),s=>s.p?.[k]||null]),[t('协议版本','Protocol version'),s=>s.p?.protocolDetails?.version||null],[t('终止条件','Termination'),s=>s.p?.protocolDetails?.termination||null],[t('步数 / 局数预算','Step / episode budget'),s=>s.p?.protocolDetails?.budget||null],[t('研究问题','Research question'),s=>s.p?model.get(s.p.id)?.question:null],[t('主要干扰因素','Principal confounds'),s=>s.p?model.get(s.p.id)?.confounds:null]];}
 function renderHTML(){const ss=mode==='tasks'?slots():slots().slice(0,current.length),rows=(mode==='tasks'?taskRows():resourceRows()).filter(([,value])=>!different||new Set(ss.map(s=>JSON.stringify(value(s)))).size>1);return `<button class="modal-close" data-close="compare-dialog" aria-label="${t('关闭对比','Close comparison')}">×</button>${window.AtlasLanguage.picker()}<h2 id="compare-title">${t('Benchmark 选型与任务对比','Benchmark selection & task comparison')}</h2><p>${context.question?esc(tr(context.question.label)):t('先确定研究用途，再对齐具体任务与实验协议。','Identify research uses, then align concrete tasks and experimental protocols.')}</p><div class="comparison-controls"><div>${[['resources',t('资源选型','Resource selection')],['tasks',t('任务协议','Task protocols')]].map(([id,name])=>`<button data-comparison-mode="${id}" aria-pressed="${mode===id}" class="${mode===id?'active':''}">${name}</button>`).join('')}</div><label><input id="comparison-differences" type="checkbox" ${different?'checked':''}> ${t('仅显示不同字段','Show differing fields')}</label><button id="share-compare">${t('复制对比链接','Copy comparison link')}</button></div><input class="compare-share-url" id="compare-link" aria-label="${t('对比链接','Comparison link')}" readonly hidden value="${esc(location.href)}">${!ss.length?`<p>${t('从目录选择研究资源加入对比。','Select research resources from the directory.')}</p>`:`<div class="compare-table-wrap"><table class="compare-table protocol-comparison"><thead><tr><th>${t('对比字段','Comparison field')}</th>${ss.map((s,i)=>`<th><strong>${esc(s.a.bibliography.name)}</strong><small>${esc(s.a.bibliography.kind)} · ${esc(s.a.bibliography.year)}</small>${mode==='tasks'?`<label class="comparison-task-picker">${t('选择具体协议','Select a protocol')}<select data-comparison-task="${esc(s.key)}" aria-label="${esc(s.a.bibliography.name)} ${t('具体任务','task')} ${i+1}">${s.opts.map(p=>`<option value="${esc(p.id)}" ${s.p?.id===p.id?'selected':''}>${esc(tr(p.label))}</option>`).join('')||`<option>${missing()}</option>`}</select></label>${s.p?`<a href="?lang=${window.AtlasLanguage.current()}&view=explore&detail=${s.id}&archiveTab=protocol&task=${encodeURIComponent(s.p.id)}">${t('来源任务','Source task')} ↗</a><button data-arena-add-protocol="${esc(s.p.id)}">${t('加入 Arena 组合','Add to Arena')}</button>`:''}${ss.length<4&&s.opts.length>1?`<button data-comparison-extra="${s.id}">${t('同资源增加任务列','Add a task column')}</button>`:''}`:''}${i<current.length?`<button data-compare="${s.id}">${t('移出','Remove')} ×</button>`:`<button data-comparison-remove-extra="${i-current.length}">${t('移出任务列','Remove task column')} ×</button>`}</th>`).join('')}</tr></thead><tbody>${rows.map(([name,value])=>`<tr><th>${name}</th>${ss.map(s=>`<td>${esc(tr(value(s)))||`<span class="comparison-unspecified">${mode==='tasks'?(s.p?t('此项未独立结构化，见配置与来源。','Not separately structured; see configuration and sources.'):missing()):t('未单独整理','Not separately documented')}</span>`}</td>`).join('')}</tr>`).join('')}${!rows.length?`<tr><td colspan="${ss.length+1}">${t('所选字段相同；可关闭差异筛选查看完整内容。','Selected fields match; disable the difference filter to inspect all fields.')}</td></tr>`:''}<tr><th>${t('来源依据','Sources')}</th>${ss.map(s=>`<td>${(mode==='tasks'?s.p?.evidence||[]:s.a.overview?.sources||s.a.sources.slice(0,2)).map(e=>`<a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(tr(e.title))} ↗</a>`).join('<br>')}</td>`).join('')}</tr></tbody></table></div>`}${mode==='tasks'?`<section class="comparison-conclusions"><h3>${t('任务关系与选型结论','Task relationships & selection')}</h3>${pairs(ss).map(({a,b,relation:r})=>`<article><h4>${esc(tr(a.p.label))} × ${esc(tr(b.p.label))}</h4><strong>${esc(tr(model.relationTypes[r.type]))||t('尚未专项判断','Not separately reviewed')}</strong><p>${esc(tr(r.summary))}</p>${r.difference?`<p>${esc(tr(r.difference))}</p><p>${esc(tr(r.recommendation))}</p>`:''}</article>`).join('')||`<p>${t('选择两个具体任务查看关系。','Choose two concrete tasks to inspect their relationship.')}</p>`}<p class="plan-caption">${t('关系结论为基于来源的编辑分析；同字段或同标签不构成受控实验。','Relationships are source-informed editorial analysis; matching fields or labels do not establish a controlled experiment.')}</p></section>`:`<p>${t('选择“任务协议”，逐列选择具体任务后比较接口、指标和条件。','Select Task protocols, then choose one concrete task per column to compare interfaces, metrics and conditions.')}</p>`}`;}
 function paint(){document.querySelector('#compare-content').innerHTML=renderHTML();}
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.comparisonMode){mode=b.dataset.comparisonMode;sync();paint();}if(b.dataset.comparisonExtra&&slots().length<4){const id=b.dataset.comparisonExtra,previous=slots().filter(s=>s.id===id),next=options(id).find(p=>!previous.some(s=>s.p?.id===p.id));extras.push(id);if(next)choices[id+':'+previous.length]=next.id;sync();paint();}if(b.hasAttribute('data-comparison-remove-extra')){const at=Number(b.dataset.comparisonRemoveExtra),remaining=slots().filter((s,i)=>i!==current.length+at),occurrences={};extras.splice(at,1);choices={};for(const s of remaining){const key=s.id+':'+(occurrences[s.id]||0);occurrences[s.id]=(occurrences[s.id]||0)+1;if(s.p)choices[key]=s.p.id;}sync();paint();}});
 document.addEventListener('change',e=>{if(e.target.dataset.comparisonTask){choices[e.target.dataset.comparisonTask]=e.target.value;sync();paint();}if(e.target.id==='comparison-differences'){different=e.target.checked;sync();paint();}});
 window.AtlasComparison={render(ids,options={}){current=ids.filter(id=>window.AtlasResearchArchives.get(id));context=options;read();return renderHTML();}};
})();
